[
  {
    "qid": "0003-t2i-1",
    "sample_id": "0003_摩根_4daff88d.webp",
    "task": "t2i",
    "knowledge_dim": "brand_commercial",
    "difficulty": "L2",
    "evidence_audit": {
      "visible_facts": [
        "画面主体是一辆深绿色的 Morgan 品牌复古双座敞篷跑车",
        "主体正在宽阔的城市道路上行驶",
        "车辆前部可见左右分置的灯具与中央竖向进气区域",
        "四个车轮采用细密金属辐条形式，前轮外露于车体轮廓之外",
        "背景包含现代建筑、路灯与道路护栏"
      ],
      "anchor_features": [
        "Morgan 经典车型常见的独立式前翼子板",
        "Morgan 复古跑车常见的外置圆形前照灯",
        "Morgan 传统外观常见的竖向窄格栅",
        "Morgan 经典敞篷车型常见的细密辐条轮",
        "Morgan 传统车身具有较长前舱与后移座舱的比例"
      ],
      "trigger_check": "能。prompt 明示 Morgan 品牌与复古英伦跑车类型，模型可依据该品牌的标志性形制完成各项视觉校验。",
      "counterexample_test": "尝试替换为现代一体式车灯、封闭式轮罩或横向宽格栅的普通敞篷车，均会失去 Morgan 的可识别形制；无法构造同时保持品牌身份且合理违反全部校验点的画面。"
    },
    "gen_prompt": "请生成一张电影感写实照片：Morgan品牌的深绿色英伦双座敞篷跑车正在现代城市道路上平稳行驶，背景为灰色建筑、路灯和护栏，采用低机位三分之四前侧视角，车辆占据画面主体，清晨柔和日光，整体呈现经典机械与当代都市并置的氛围。",
    "implicit_checks": [
      {
        "check": "车辆前端左右各有一盏独立外置的圆形前照灯，中央进气格栅呈窄长竖向排列",
        "knowledge": "[solid] Morgan 经典跑车沿袭英伦老式跑车的前端布局：独立外置圆灯与竖向窄格栅是高辨识度形制特征。",
        "verified": true,
        "weight": 0.4,
        "rubric": {
          "0": "缺少可识别的前端灯具，或采用现代横向灯带和大尺寸封闭式前脸",
          "1": "具备两侧灯具或中央进气区域，但灯具位置、数量或进气区域形状明显偏离经典形制",
          "2": "左右各一盏独立外置圆灯，中央为窄长竖向格栅，前端三项关系同时成立"
        },
        "acceptable_variants": [
          "由于拍摄角度或轻微遮挡，一侧灯具部分不可见，但另一侧与中央格栅清晰呈现",
          "灯具使用轻微暖色反光或玻璃高光，但仍保持独立外置圆形结构"
        ]
      },
      {
        "check": "四个车轮均呈细密金属辐条结构，前轮位于独立外凸的轮罩之中并保持外露状态",
        "knowledge": "[solid] Morgan 传统跑车保留外露式独立轮罩与辐条轮的经典英伦跑车布局，区别于现代封闭式轮拱和合金多辐轮。",
        "verified": true,
        "weight": 0.3,
        "rubric": {
          "0": "车轮被完整包入流线型车体，或使用封闭轮毂、塑料轮盖等非辐条结构",
          "1": "部分车轮可见辐条或外凸轮罩，但前后轮形式不一致或轮罩未形成独立外露布局",
          "2": "可见车轮均采用细密金属辐条，前轮由独立外凸轮罩包覆且轮胎明显外露"
        },
        "acceptable_variants": [
          "远侧车轮被车体遮挡，但近侧前后轮清晰呈现辐条与独立轮罩",
          "辐条因运动模糊略有虚化，但轮毂仍可辨认为金属辐条结构"
        ]
      },
      {
        "check": "跑车具有较长前舱、后移座舱和低矮双座比例，未呈现前后空间均匀的现代短舱布局",
        "knowledge": "[solid] Morgan 经典前置发动机跑车的车身比例通常由长前舱、短后舱和低矮座舱构成，这是其传统车型外观识别的重要依据。",
        "verified": true,
        "weight": 0.3,
        "rubric": {
          "0": "车辆呈现短前舱或前后空间均匀的现代化比例，无法辨认传统长前舱跑车布局",
          "1": "具有低矮姿态或双座特征，但前舱长度与座舱后移关系表现不清晰",
          "2": "长前舱、后移座舱、低矮双座三项比例关系清楚，整体符合传统 Morgan 跑车布局"
        },
        "acceptable_variants": [
          "采用近距离前侧视角导致后部比例部分隐藏，但长前舱与后移座舱仍清楚可见",
          "软顶收起或半收起不影响长前舱与低矮双座比例的判定"
        ]
      }
    ],
    "facet_tags": [
      "tech_machinery",
      "objects",
      "subject_prominence",
      "composition"
    ],
    "gate_spec": {
      "required_subjects": [
        "Morgan品牌复古敞篷跑车"
      ],
      "theme_definition": "现代城市道路中行驶的经典 Morgan 英伦敞篷跑车"
    },
    "expected_failure_modes": [
      "将 Morgan 画成现代跑车，使用一体式细长灯带和封闭式大进气口",
      "使用封闭轮拱与现代合金轮毂，缺少外露轮罩和细密辐条轮",
      "把车身比例画成短前舱、前移座舱的现代敞篷车型"
    ],
    "notes": "利用 Morgan 的经典前端、轮组与车身比例考察品牌产品形制知识，避免仅凭绿色复古外观蒙对。"
  }
]
